/* eslint-disable react/no-array-index-key */
/* eslint-disable no-nested-ternary */
import React, { useEffect, useMemo, useState } from 'react';
import {
  FileTextOutlined,
  UnorderedListOutlined,
  WarningOutlined,
  CopyOutlined,
  UpOutlined,
  DownOutlined,
  LeftOutlined
} from '@ant-design/icons';
import { Collapse, Button, Tooltip, message } from 'antd';
import ReactLoader from 'components/common/reactLoading';
import { CopyToClipboard } from 'react-copy-to-clipboard';
import { useSelector } from 'react-redux';
import {
  useCrashLog,
  useCrashSession,
} from 'components/features/sessions/hooks/useSessionDetail';
import { useSessionHeader, useSessionTimeLine } from 'components/shared/Sessions/Context';
import styled from 'styled-components';

const ButtonGroup = Button.Group;
const { Panel } = Collapse;

const ANDROID_SDK_VERSION_NUMBER_THRESHOLD = 501; // 3.3.0
const IOS_SDK_VERSION_NUMBER_THRESHOLD = 20200521; // 3.2.2

const BackToReplayBtn = styled.div`
  display: inline-block;
  margin: 0px 0px 0px 15px;
  .ant-btn{
    border-radius: 4px;
    border: 1px solid rgba(165, 165, 165, 0.4);
    color: #5D97FF;
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    height: 30px;
    line-height: 30px;
    padding: 0px 10px;
  }
`
const StackTraceBoxWrapper = styled.div`
  position: relative;
  height: 100%;
  .ant-collapse{
    padding-left: 15px;
    padding-right: 15px;
    height: calc(100vh - 288px) !important;
  }
  .stack-trace-header{
    padding:10px 32px 0 20px;
  }
`

const LoaderWrapper = styled.div`
  width: 100%;
  height: 100%;
`

const StackTrace = () => {
  const { currentOrgReducer: currentOrg, urlReducer: urlQuery } = useSelector(
    (state) => state
  );
  const { setSelectedHeaderField } = useSessionHeader();
  const { sessionDetail, setVideoLimitPopup, videoLimitPopup } = useSessionTimeLine();
  const [buttonClick, setButtonClick] = useState('list');
  const [oldCrashData, setOldCrashData] = useState('');

  const { appId, platform, isStructured, crashLogData: crashLog  } = sessionDetail;
  const { shareSessionKey, appId: urlAppId, sessionid } = urlQuery;
  const sessionId = sessionDetail['_id'];

  const reqBody = useMemo(() => ({
    ...(!shareSessionKey && { appid: urlAppId || appId,
    sessionid: sessionid || sessionId,}),
    ...(shareSessionKey && { shareSessionKey }),
  }), [appId, sessionId, sessionid, shareSessionKey, urlAppId])
  const endpoint = shareSessionKey ? '/crashes/public/crash_logs' : '/crashes/crash_logs';
  const urlkey = shareSessionKey ? '/share/app/' : '/app/';
  const {
    isLoading: isCrashDataLoading,
    isFetching: isCrashFetching,
    data: newCrashData,
    refetch: fetchCrashSession,
    error,
    isError,
  } = useCrashSession(endpoint, reqBody);
  const { data: crashLogData, isLoading, isFetching } = useCrashLog(urlkey, appId, sessionId);

  const crashData = newCrashData?.data?.data;

  const exceptionHeader = (name, method) => (
    <div className="exception-title">
      <h4>{`${name}`}</h4>
      <p>{`${method}`}</p>
    </div>
  );

  const handleButtonClick = (value) => {
    setButtonClick(value);
  };

  const crashDownload = async () => {
    if ( !sessionDetail.isPlayable || sessionDetail.verifiedPastVideoRecordingLimit) {
      setVideoLimitPopup(!videoLimitPopup)
      return;
    }
    if (!sessionDetail?.isPlayable) {
      message.info(
        <span>
          Please{' '}
          <a
            style={{ textDecoration: 'underline' }}
            href={`${process.env.REDIRECT_URL}/settings/org/${currentOrg.orgId}/plan`}
          >
            upgrade your plan
          </a>{' '}
          to enable this feature or get in touch with the customer success team.
        </span>,
        5
      );
    }
  };

  const crashLogText = useMemo(() => {
    const newCrashLogText = [];
    const exceptionValue = crashData?.exceptions;
    const threadValue = crashData?.threads;
    if (exceptionValue instanceof Array) {
      exceptionValue.map((obj) => {
        newCrashLogText.push(
          `\n ${obj.name} : ${obj.method_name} :  ${obj.reason}`
        );
          typeof obj?.callstack === 'object' && obj?.callstack?.map((value) =>
            newCrashLogText.push(
              platform === 1
                ? `\n \t at ${''}${value} `
                : `\n \t ${value}`
            )
          );
      });
    }

    if (threadValue instanceof Array) {
      threadValue.map((obj) => {
        newCrashLogText.push(`\n ${obj.name}: ${obj.method_name}`);
        if (obj.backtrace) {
          obj.backtrace.map((value) =>
            newCrashLogText.push(
              platform === 1
                ? `\n \t at ${''}${value} `
                : `\n \t ${value}`
            )
          );
        }
        if (obj.properties) {
          newCrashLogText.push(`\n with additional properties`);
          Object.keys(obj.properties).map((key) => {
            newCrashLogText.push(`\n \t \t \t ${key} : ${obj.properties[key]}`);
          });
        }
      });
    }
    return newCrashLogText;
  }, [crashData]);

  useEffect(() => {
    setOldCrashData(crashLogData);
  }, [crashLogData]);

  useEffect(() => {
    if (isStructured) {
      fetchCrashSession({ appid: appId, sessionid: sessionId });
    }
    if (crashLog) {
      crashDownload();
    }
    return () => {
      setButtonClick('list');
    };
  }, [sessionDetail['_id']]);

  const isCrashLogValid = useMemo(() => {
    if (sessionDetail?.device) {
      const threshold =
        platform === 1 ? ANDROID_SDK_VERSION_NUMBER_THRESHOLD : IOS_SDK_VERSION_NUMBER_THRESHOLD;
      return (sessionDetail?.device?.sdkVersionNumber ?? 0) >= threshold;
    }
    return null;
  }, [sessionDetail?.device, platform]);

  const errorMessage = useMemo(() => {
    // check sdk version and display const message
    if (!isCrashLogValid)
      return `To see a full stack trace of the crash please upgrade your SDK to version ${
        platform === 1 ? '3.3.0' : '3.2.2'
      } or higher.`;
    if (error?.response?.data?.error?.message) {
      return error?.response?.data?.error?.message;
    }
    return 'Crash does not exist for this session.';
  }, [isError, error, isCrashLogValid, platform]);

  return (
    <StackTraceBoxWrapper>
    {!isCrashDataLoading ?
      <div className="stack-trace-box">
        <BackToReplayBtn>
          <Button onClick={() => setSelectedHeaderField('sessionVideo')}><LeftOutlined/> Back to replay</Button>
        </BackToReplayBtn>
        {isStructured && crashData ? (
          <div>
            <div className="stack-trace-header">
              <div className="stack-trace-header-title">
                <Tooltip title={crashData?.title || ''}>
                  <h4>{crashData?.title?.trim() || ''}</h4>
                </Tooltip>
                <Tooltip title={crashData.subtitle}>
                  <p className="thread-summary">
                    {crashData.subtitle?.trim() || ''}
                  </p>
                </Tooltip>
              </div>
              <div className="button-group">
                <ButtonGroup>
                  <Tooltip title="List view">
                    <Button
                      icon={<UnorderedListOutlined />}
                      onClick={() => handleButtonClick('list')}
                      type={buttonClick === 'list' ? 'active' : ''}
                      className="btn-list-view"
                    />
                  </Tooltip>
                  <Tooltip title="Text view">
                    <Button
                      icon={<FileTextOutlined />}
                      onClick={() => handleButtonClick('text')}
                      type={buttonClick === 'text' ? 'active' : ''}
                      className="btn-text-view"
                    />{' '}
                  </Tooltip>
                  <CopyToClipboard
                    onCopy={() => {}}
                    text={
                      isStructured
                        ? crashLogText
                        : oldCrashData?.crashLog
                    }
                  >
                    <Tooltip title="Copy crash log">
                      <Button
                        icon={<CopyOutlined />}
                        onClick={() =>
                          message.success(
                            'Log message for the Crash has been copied to clipboard.'
                          )
                        }
                        className="btn-copy"
                      />
                    </Tooltip>
                  </CopyToClipboard>
                </ButtonGroup>
              </div>
            </div>
            <Collapse
              defaultActiveKey={['0']}
              expandIconPosition="right"
              expandIcon={({ isActive }) =>
                isActive ? <UpOutlined /> : <DownOutlined />
              }
              className={
                buttonClick === 'text'
                  ? 'custom-scrollbar crashlog-textview'
                  : 'custom-scrollbar'
              }
            >
              {crashData &&
                crashData.exceptions instanceof Array &&
                crashData.exceptions.map((obj, index) => (
                  <Panel
                    header={exceptionHeader(obj.name, obj.reason)}
                    key={index}
                    extra={obj.method_name}
                  >
                    {buttonClick === 'text' && (
                      <ul key="ab01" className="title">
                        <li>{`${obj.name}:${' '} ${obj.reason}:${' '} ${
                          obj.method_name
                        }`}</li>{' '}
                      </ul>
                    )}
                    <ul className="threads">
                      {obj?.callstack && typeof obj?.callstack === 'object' &&
                        obj?.callstack?.map((value, threadIndex) => (
                          <li key={threadIndex}>
                            {buttonClick === 'text' && platform === 1
                              ? `at${' '} ${value}`
                              : value}
                          </li>
                        ))}
                    </ul>
                  </Panel>
                ))}

              {crashData?.threads instanceof Array &&
                crashData?.threads?.map((obj, index) => (
                  <Panel
                    header={<span className="panel-title">{obj.name}</span>}
                    key={`a${index}`}
                    extra={obj.method_name}
                  >
                    {buttonClick === 'text' && (
                      <ul className="title" key="ab01">
                        <li>{`${obj.name}:${''} ${obj.method_name}`}</li>
                      </ul>
                    )}
                    <ul className="threads">
                      {obj.backtrace &&
                        obj.backtrace.map((value, threadIndex) => (
                          <li key={threadIndex}>
                            {buttonClick === 'text' && platform === 1
                              ? `at${' '} ${value}`
                              : value}
                          </li>
                        ))}
                    </ul>
                  </Panel>
                ))}
            </Collapse>
          </div>
        ) : oldCrashData?.crashLog ? (
          <div className="crash-thread-old custom-scrollbar">
            {oldCrashData?.crashLog}
          </div>
        ) : crashLogData &&
          typeof newCrashData?.message !== 'string' ? (
            <LoaderWrapper><ReactLoader /></LoaderWrapper>
        ) :
        isLoading || isFetching ? (
          <LoaderWrapper><ReactLoader /></LoaderWrapper>
        ) :(
          <div
            style={{ alignItems: 'center', height: '70px', width: '220px' }}
            className="no-data-msg-box"
          >
            <WarningOutlined style={{ margingRight: '10px' }} />
            {
              isError ? errorMessage :
              `To see a full stack trace of the crash please upgrade your SDK to version ${
                platform === 1 ? '3.3.0' : '3.2.2'
              } or higher.`
            }
          </div>
        )}
      </div> :
        isCrashDataLoading || isCrashFetching ? (
          <LoaderWrapper><ReactLoader /></LoaderWrapper>) : null}
    </StackTraceBoxWrapper>
  );
};
export default StackTrace;
